const main=document.querySelector('main');
const title=(tag,h,sub='')=>`<div class="page-title"><span class="eyebrow">${tag}</span><h1>${h}</h1>${sub?`<p class="intro">${sub}</p>`:''}</div>`;
const sections=`<div class="cards">${[['01','Maternelle','Les premiers pas pour apprendre, découvrir et grandir.'],['02','Primaire','Construire les bases de la lecture, du calcul et de la réflexion.'],['03','Secondaire','Approfondir ses connaissances et préparer son avenir.']].map(([n,h,p])=>`<article class="card"><span class="num">${n}</span><h3>${h}</h3><p>${p}</p><a href="#admissions">Se renseigner sur l’admission ↗</a></article>`).join('')}</div>`;
const pages={accueil:()=>`<section class="hero"><div class="hero-copy"><span class="eyebrow">Collège L’Harmattan · Lubumbashi</span><h1>Travail.<br>Maîtrise.<br><em>Droiture.</em></h1><p>De la maternelle au secondaire, découvrez le Collège L’Harmattan, au cœur de Golf Karavia, Plateau Karavia.</p><div class="actions"><a class="btn" href="#admissions">Demander une inscription ↗</a><a class="btn secondary" href="#college">Découvrir le collège</a></div></div><div class="art"><img class="crest" src="./assets/logo.png" alt="Collège L’Harmattan — Travail, Maîtrise, Droiture"><div class="art-label">TRAVAIL · MAÎTRISE · DROITURE</div></div></section><div class="strip"><div><b>Travail</b><p>Apprendre avec engagement.</p></div><div><b>Maîtrise</b><p>Progresser avec méthode.</p></div><div><b>Droiture</b><p>Grandir avec intégrité.</p></div></div><section class="section"><div class="section-head"><div><span class="eyebrow">Un parcours, trois étapes</span><h2>À chaque âge,<br>de nouvelles découvertes.</h2></div><a class="text-link" href="#sections">Explorer nos sections ↗</a></div>${sections}</section><section class="callout"><div><span class="eyebrow" style="color:#b6caff">Rencontrons-nous</span><h2>Une question sur la scolarité ?</h2><p>Retrouvez-nous avenue Bunduki, à Golf Karavia, Plateau Karavia.</p></div><a class="btn" href="#contact">Nous trouver ↗</a></section>`,college:()=>title('Notre identité','Le Collège L’Harmattan','Un établissement à Lubumbashi, de la maternelle au secondaire.')+`<section class="section twocol prose"><div><h2>Travail, Maîtrise, Droiture.</h2><p>Ces trois mots, inscrits sur le blason du collège, donnent le ton de son identité.</p><p>Le Collège L’Harmattan se situe sur l’avenue Bunduki, à Golf Karavia, Plateau Karavia, dans la ville de Lubumbashi.</p><a class="btn" href="#sections">Découvrir les sections</a></div><div><img src="./assets/logo.png" alt="Logo officiel du collège" style="display:block;height:290px;margin:auto"><p class="notice">La présentation de la direction, l’histoire du collège et son projet pédagogique seront ajoutés après transmission des textes officiels.</p></div></section>`,sections:()=>title('L’enseignement','Nos trois sections','Un parcours scolaire de la petite enfance aux études secondaires.')+`<section class="section">${sections}<p class="notice" style="margin-top:30px">Les classes ouvertes, les options du secondaire et les programmes détaillés seront précisés par la direction.</p></section>`,admissions:()=>title('Rejoindre le collège','Préparer une inscription','Une première démarche pour échanger avec le secrétariat.')+`<section class="section twocol"><div class="prose"><h2>Votre démarche,<br>étape par étape.</h2><div class="steps"><div class="step"><b>01 · Choisir la section</b><p>Maternelle, primaire ou secondaire.</p></div><div class="step"><b>02 · Rencontrer le secrétariat</b><p>Rendez-vous au collège pour connaître les places disponibles et les conditions d’admission.</p></div><div class="step"><b>03 · Constituer le dossier</b><p>Le secrétariat vous précisera les pièces à fournir, les frais et les modalités de validation.</p></div></div></div><div><h3>Préparer ma demande</h3><p class="notice">Formulaire de démonstration : aucune donnée n’est envoyée ni conservée. Le service de préinscription sera raccordé à la plateforme de gestion.</p><form id="admission"><label for="section">Section souhaitée</label><select id="section" required><option value="">Choisir une section</option><option>Maternelle</option><option>Primaire</option><option>Secondaire</option></select><label for="classe">Classe souhaitée (facultatif)</label><input id="classe" placeholder="Ex. : 3e primaire" maxlength="80"><button class="btn" type="submit">Afficher les prochaines étapes →</button><div id="result" aria-live="polite"></div></form></div></section>`,contact:()=>title('Nous rencontrer','Bienvenue à Golf Karavia, Plateau Karavia.','Le secrétariat du collège vous renseigne sur place.')+`<section class="section twocol prose"><div><span class="eyebrow">Notre adresse</span><h2>Avenue Bunduki<br>Golf Karavia, Plateau Karavia, Lubumbashi</h2><p>République démocratique du Congo</p><a class="btn" href="https://www.google.com/maps/search/?api=1&query=Avenue+Bunduki+Golf+Karavia+Plateau+Karavia+Lubumbashi" target="_blank" rel="noopener">Rechercher l’avenue sur la carte ↗</a><p style="font-size:12px">Le repère exact du collège reste à confirmer.</p></div><div class="card"><h3>Avant votre visite</h3><p>Les numéros de téléphone, l’adresse e-mail et les horaires d’accueil seront affichés après confirmation par le collège.</p><p>Pour une inscription, consultez d’abord les étapes proposées.</p><a href="#admissions">Préparer mon inscription →</a></div></section>`,espace:()=>title('Plateforme de gestion','L’espace scolaire','Un point d’accès pour les équipes du collège et, à terme, les familles.')+`<section class="section"><p class="notice">Aperçu du périmètre prévu. La connexion et la base de données ne sont pas encore activées.</p><div class="cards" style="margin-top:30px"><article class="card"><span class="num">01</span><h3>Administration</h3><p>Élèves, inscriptions, classes et suivi des présences.</p></article><article class="card"><span class="num">02</span><h3>Pédagogie</h3><p>Enseignants, cours, notes et bulletins scolaires.</p></article><article class="card"><span class="num">03</span><h3>Comptabilité</h3><p>Frais scolaires, paiements et reçus.</p></article></div></section>`};
const opts=['Littéraire','Scientifique','CG','Électricité'];
const classes={Maternelle:['1re maternelle','2e maternelle','3e maternelle'],Primaire:Array.from({length:6},(_,i)=>`${i===0?'1re':(i+1)+'e'} primaire`),Secondaire:['7e éducation de base','8e éducation de base','1re humanités','2e humanités','3e humanités','4e humanités']};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const select=(id,values)=>`<select id="${id}" name="${id}" required><option value="">Choisir</option>${values.map(v=>`<option>${esc(v)}</option>`).join('')}</select>`;
const field=(name,label,type='text',required=true)=>`<label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" ${required?'required':''} maxlength="140">`;
const originalCollege=pages.college;
pages.college=()=>originalCollege()+`<section class="section prose"><h2>Histoire et promoteur</h2><p>Pour découvrir les publications et les photos de l’établissement, consultez son site officiel. La biographie du promoteur sera intégrée après vérification de son identité et validation du texte par le collège.</p><a class="btn secondary" href="https://www.collegelharmattan.com/" target="_blank" rel="noopener">Publications et photos du collège ↗</a></section>`;
pages.sections=()=>title('L’enseignement','Maternelle, primaire et secondaire')+`<section class="section">${sections}<h2>Les filières du secondaire</h2><div class="tabs">${opts.map(o=>`<a class="btn secondary" href="#admissions">${o} · S’inscrire →</a>`).join('')}</div></section>`;
pages.admissions=()=>title('Admissions','Préparer une inscription','Choisissez le parcours de votre enfant puis complétez sa fiche.')+`<section class="section twocol"><div class="prose"><h2>Une démarche simple</h2><div class="step"><a href="#choix" id="choose"><b>01 · Choisir la section →</b></a><p>Maternelle, primaire ou secondaire, puis la classe souhaitée.</p></div><div class="step"><a href="#dossier" id="documents"><b>02 · Constituer le dossier →</b></a><p>Consultez les pièces proposées ci-dessous.</p></div><div id="dossier"><h3>Pièces à préparer</h3><ul><li>Copie de l’acte de naissance ou attestation de naissance.</li><li>Bulletins des années antérieures, pour un élève déjà scolarisé.</li><li>Photo d’identité récente.</li><li>Coordonnées du parent ou responsable légal.</li></ul><p class="notice">Liste indicative, à confirmer par la direction. Aucun document n’est téléversé à ce stade.</p></div></div><div id="choix"><h3>Préparer ma demande</h3><form id="admission"><label for="section">Section souhaitée</label>${select('section',Object.keys(classes))}<label for="classe">Classe souhaitée</label>${select('classe',[])}<div id="option-wrap" hidden><label for="option">Filière souhaitée</label>${select('option',opts)}</div><button class="btn">Afficher les prochaines étapes →</button></form><div id="fiche"></div></div></section>`;
pages.contact=()=>title('Contact','Golf Karavia, Plateau Karavia','Avenue Bunduki · Lubumbashi · RDC')+`<section class="section twocol prose"><div><h2>Nous trouver</h2><p>Avenue Bunduki, Golf Karavia, Plateau Karavia, Lubumbashi.</p><a class="btn" href="https://www.google.com/maps/search/?api=1&query=Avenue+Bunduki+Plateau+Karavia+Lubumbashi" target="_blank" rel="noopener">Voir le secteur sur la carte ↗</a></div><div class="card"><h3>Nous contacter</h3><p>E-mail publié sur le site du collège :</p><a href="mailto:lharmattancollege@gmail.com">lharmattancollege@gmail.com</a><p>Contact provisoire AMMGROUP Digital : numéro à renseigner par le responsable du projet.</p></div></section>`;
let demo;try{demo=JSON.parse(localStorage.getItem('harmattan-demo-v2'))}catch{};
demo ||= {students:[{id:'DEMO-001',name:'Élève Exemple A',section:'Primaire',classe:'3e primaire',parent:'Parent Exemple A',due:100,paid:100},{id:'DEMO-002',name:'Élève Exemple B',section:'Secondaire',classe:'1re humanités',parent:'Parent Exemple B',due:100,paid:40},{id:'DEMO-003',name:'Élève Exemple C',section:'Maternelle',classe:'2e maternelle',parent:'',due:100,paid:0}],teachers:['Enseignant Exemple 1','Enseignant Exemple 2'],slots:[{classe:'3e primaire',day:'Lundi',start:'08:00',end:'08:50',course:'Mathématiques',teacher:'Enseignant Exemple 1'}],payments:[],notifications:[],results:[{student:'DEMO-001',course:'Mathématiques',score:16,max:20,period:'1er trimestre'}]};
const save=()=>localStorage.setItem('harmattan-demo-v2',JSON.stringify(demo));
let role='',tab='eleves',student=null;
const table=(heads,rows)=>`<div class="table-scroll"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${heads.length}">Aucun élément.</td></tr>`}</tbody></table></div>`;
const studentOpts=()=>demo.students.map(s=>s.id+' · '+s.name);
function portalContent(){
 if(role==='Élève')return `<h2>Bonjour ${esc(student.name)}</h2><h3>Mon horaire</h3>${schedule(student.classe)}<h3>Mes résultats</h3>${table(['Cours','Période','Résultat'],demo.results.filter(r=>r.student===student.id).map(r=>[esc(r.course),esc(r.period),`${r.score} / ${r.max}`]))}`;
 if(tab==='eleves')return `<h2>Élèves et situation des frais</h2><label for="filter">Situation de paiement</label>${select('filter',['Tous','Payés','Partiels','Non payés'])}<div id="students-table"></div><h3>Ajouter un élève fictif</h3><form id="add-student" class="gridform">${field('nom','Nom complet')}${field('parent','Nom du parent lié', 'text',false)}<label>Section${select('sec',Object.keys(classes))}</label><label>Classe${select('cl',Object.values(classes).flat())}</label>${field('due','Frais attendus (USD)','number')}<button class="btn">Ajouter</button></form>`;
 if(tab==='horaires')return `<h2>Horaires et affectation</h2>${schedule()}<h3>Ajouter un cours à l’horaire</h3><form id="slot" class="gridform"><label>Classe${select('cl',Object.values(classes).flat())}</label><label>Jour${select('day',['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi'])}</label>${field('start','Début','time')}${field('end','Fin','time')}${field('course','Cours')}<label>Enseignant${select('teacher',demo.teachers)}</label><button class="btn">Affecter le cours</button></form>`;
 if(tab==='enseignants')return `<h2>Enseignants</h2>${table(['Nom'],demo.teachers.map(t=>[esc(t)]))}<form id="teacher">${field('name','Nom de l’enseignant')}<button class="btn">Ajouter un enseignant fictif</button></form>`;
 if(tab==='notes')return `<h2>Résultats scolaires</h2>${table(['Élève','Cours','Période','Note'],demo.results.map(r=>[esc(r.student),esc(r.course),esc(r.period),`${r.score}/${r.max}`]))}<form id="grade" class="gridform"><label>Élève${select('student',studentOpts())}</label>${field('course','Cours')}${field('period','Période')}${field('score','Note obtenue','number')}${field('max','Maximum','number')}<button class="btn">Enregistrer le résultat</button></form>`;
 if(tab==='paiements')return `<h2>Valider un paiement</h2><p>La validation crée un reçu et une confirmation dans la boîte du parent lié. Aucun message externe n’est envoyé dans cette version.</p><form id="payment" class="gridform"><label>Élève${select('student',studentOpts())}</label>${field('amount','Montant reçu (USD)','number')}<label>Mode${select('method',['Espèces','Virement','Mobile Money'])}</label>${field('reference','Référence de paiement')}<label><input type="checkbox" required> Je confirme avoir vérifié ce paiement fictif.</label><button class="btn">Valider et générer le reçu</button></form><div id="receipt"></div><h3>Historique</h3>${table(['Reçu','Élève','Montant','Mode'],demo.payments.map(p=>[esc(p.id),esc(p.name),p.amount+' USD',esc(p.method)]))}`;
 return `<h2>Confirmations aux parents</h2><p>Boîte de démonstration des confirmations créées après validation du paiement.</p>${table(['Parent','Élève','Confirmation'],demo.notifications.map(n=>[esc(n.parent),esc(n.name),esc(n.text)]))}`;
}
function schedule(cl){return table(['Classe','Jour','Heure','Cours','Enseignant'],demo.slots.filter(s=>!cl||s.classe===cl).map(s=>[esc(s.classe),esc(s.day),esc(s.start+' – '+s.end),esc(s.course),esc(s.teacher)]))}
pages.espace=()=>title('Plateforme scolaire','La gestion du collège','Administration, enseignants et espace élève.')+`<section class="section"><p class="notice">Version de démonstration · Données fictives sauvegardées uniquement dans ce navigateur. Les rôles ci-dessous servent à tester les parcours et ne constituent pas une connexion sécurisée. N’ajoutez pas de données réelles.</p>${!role?`<div class="cards"><article class="card"><h3>Administration</h3><p>Élèves, horaires, paiements et reçus.</p><button class="btn" data-role="Administration">Ouvrir la démonstration</button></article><article class="card"><h3>Enseignants</h3><p>Horaires, affectations et résultats.</p><button class="btn" data-role="Enseignant">Ouvrir la démonstration</button></article><article class="card"><h3>Élève</h3><p>Consulter son horaire et ses résultats.</p><form id="student-login">${field('name','Nom')}${field('code','Code ID')}<button class="btn">Consulter</button><p>Test : Élève Exemple A / DEMO-001</p><p id="login-error" role="alert"></p></form></article></div>`:`<div class="portalbar"><b>${esc(role)}</b><button class="btn secondary" id="logout">Quitter cet espace</button></div>${role!=='Élève'?`<div class="tabs">${(role==='Enseignant'?['horaires','notes']:['eleves','enseignants','horaires','notes','paiements','confirmations']).map(t=>`<button class="btn ${tab===t?'':'secondary'}" data-tab="${t}">${({eleves:'Élèves',enseignants:'Enseignants',horaires:'Horaires',notes:'Résultats',paiements:'Paiements',confirmations:'Parents'})[t]}</button>`).join('')}</div>`:''}<div id="workspace">${portalContent()}</div>`}</section>`;
function drawStudents(){let f=document.querySelector('#filter').value;document.querySelector('#students-table').innerHTML=table(['ID','Élève / classe','Parent lié','Attendu','Payé','Solde','Situation'],demo.students.filter(s=>f==='Tous'||!f||(f==='Payés'?s.paid>=s.due:f==='Partiels'?s.paid>0&&s.paid<s.due:s.paid===0)).map(s=>[esc(s.id),esc(s.name)+'<br>'+esc(s.classe),esc(s.parent)||'Non lié',s.due+' USD',s.paid+' USD',(s.due-s.paid)+' USD',`<span class="badge">${s.paid>=s.due?'Payé':s.paid?'Partiel':'Non payé'}</span>`]));}
function bindPortal(){document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{role=b.dataset.role;tab=role==='Enseignant'?'horaires':'eleves';render()});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});const on=(id,fn)=>{let f=document.getElementById(id);if(f)f.onsubmit=e=>{e.preventDefault();fn(Object.fromEntries(new FormData(f)));}};let lo=document.querySelector('#logout');if(lo)lo.onclick=()=>{role='';student=null;render()};on('student-login',d=>{student=demo.students.find(s=>s.id===d.code.trim()&&s.name.toLowerCase()===d.name.trim().toLowerCase());if(student){role='Élève';render()}else document.querySelector('#login-error').textContent='Nom ou code ID incorrect.'});if(document.querySelector('#filter')){document.querySelector('#filter').value='Tous';drawStudents();document.querySelector('#filter').onchange=drawStudents;}
on('add-student',d=>{if(Number(d.due)<=0||!classes[d.sec].includes(d.cl))return alert('Vérifiez la classe, la section et les frais.');demo.students.push({id:'DEMO-'+String(demo.students.length+1).padStart(3,'0'),name:d.nom,parent:d.parent,section:d.sec,classe:d.cl,due:Number(d.due),paid:0});save();render()});on('teacher',d=>{if(!demo.teachers.includes(d.name)){demo.teachers.push(d.name);save();render()}});on('slot',d=>{if(d.start>=d.end)return alert('La fin doit suivre le début.');if(demo.slots.some(s=>s.day===d.day&&s.start<d.end&&s.end>d.start&&(s.classe===d.cl||s.teacher===d.teacher)))return alert('Conflit : la classe ou l’enseignant est déjà occupé.');demo.slots.push({...d,classe:d.cl});save();render()});on('grade',d=>{if(+d.max<=0||+d.score<0||+d.score>+d.max)return alert('Note invalide.');demo.results.push({...d,student:d.student.split(' · ')[0],score:+d.score,max:+d.max});save();render()});on('payment',d=>{let s=demo.students.find(s=>d.student.startsWith(s.id+' · '));if(+d.amount<=0||+d.amount>s.due-s.paid)return alert('Le montant doit être positif et ne pas dépasser le solde.');if(demo.payments.some(p=>p.reference===d.reference))return alert('Référence déjà utilisée.');s.paid=Math.round((s.paid+Number(d.amount))*100)/100;let p={...d,amount:+d.amount,name:s.name,id:'REC-DEMO-'+String(demo.payments.length+1).padStart(4,'0')};demo.payments.push(p);if(s.parent)demo.notifications.push({parent:s.parent,name:s.name,text:`Paiement confirmé : ${p.amount} USD. Reçu ${p.id}. Solde : ${s.due-s.paid} USD.`});save();render();document.querySelector('#receipt').innerHTML=`<article class="success"><h3>Reçu ${esc(p.id)}</h3><p>${esc(s.name)} · ${p.amount} USD · ${esc(p.method)}<br>Référence : ${esc(p.reference)}<br>Solde : ${s.due-s.paid} USD</p><p>${s.parent?'Confirmation disponible dans la boîte du parent lié.':'Aucun parent lié : confirmation en attente de liaison.'}</p><button class="btn" onclick="window.print()">Imprimer le reçu</button></article>`;});}
function bindAdmission(){const form=document.querySelector('#admission');if(!form)return;const section=document.querySelector('#section'),cl=document.querySelector('#classe'),op=document.querySelector('#option');section.onchange=()=>{cl.innerHTML='<option value="">Choisir une classe</option>'+(classes[section.value]||[]).map(c=>`<option>${c}</option>`).join('');document.querySelector('#option-wrap').hidden=section.value!=='Secondaire';op.required=section.value==='Secondaire';};op.required=false;form.onsubmit=e=>{e.preventDefault();const path=[section.value,cl.value,section.value==='Secondaire'?op.value:''].filter(Boolean).join(' · ');document.querySelector('#fiche').innerHTML=`<h3>Fiche de préinscription</h3><p>${esc(path)}</p><p class="notice">Remplissez puis imprimez votre fiche. Elle n’est pas transmise au collège dans cette version.</p><form id="registration">${field('child','Nom complet de l’enfant')}${field('birth','Date de naissance','date')}${field('guardian','Nom du parent ou responsable')}${field('phone','Téléphone du parent','tel')}${field('email','E-mail','email',false)}${field('school','École précédente','text',false)}<label><input type="checkbox" required> Je confirme l’exactitude des informations.</label><button class="btn">Préparer la fiche imprimable</button></form><div id="registration-result"></div>`;document.querySelector('#registration').onsubmit=ev=>{ev.preventDefault();let d=Object.fromEntries(new FormData(ev.target));document.querySelector('#registration-result').innerHTML=`<article class="success"><h3>Fiche de préinscription · L’Harmattan</h3><p>${esc(path)}</p><p>Élève : ${esc(d.child)}<br>Naissance : ${esc(d.birth)}<br>Responsable : ${esc(d.guardian)}<br>Téléphone : ${esc(d.phone)}<br>E-mail : ${esc(d.email)}<br>École précédente : ${esc(d.school)}</p><p>À joindre : acte de naissance, photo et bulletins antérieurs selon la situation. Admission soumise à validation par le collège.</p><button class="btn" onclick="window.print()">Imprimer ma fiche</button></article>`;document.querySelector('#registration-result').scrollIntoView({behavior:'smooth'});};document.querySelector('#fiche').scrollIntoView({behavior:'smooth'});};['choose','documents'].forEach((id,i)=>{document.getElementById(id).onclick=e=>{e.preventDefault();document.getElementById(i?'dossier':'choix').scrollIntoView({behavior:'smooth'});if(!i)section.focus();}});}
const iconPaths={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3z',calendar:'M4 5h16v16H4z M4 10h16 M8 3v4 M16 3v4',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M20 8v6 M17 11h6',book:'M12 6c-3-3-7-3-10-2v15c4-1 7 0 10 2 3-2 6-3 10-2V4c-3-1-7-1-10 2v15',money:'M12 2v20 M18 6H9a4 4 0 0 0 0 8h6a4 4 0 0 1 0 8H5',receipt:'M5 3l3 2 4-2 4 2 3-2v19l-3-2-4 2-4-2-3 2z M8 10h8 M8 14h8',result:'M4 3v18h17 M8 16l4-5 4 2 5-7',profile:'M20 21v-2a6 6 0 0 0-6-6h-4a6 6 0 0 0-6 6v2 M12 9a4 4 0 1 0 0-8 4 4 0 0 0 0 8',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',card:'M2 5h20v15H2z M6 9h4v4H6z M14 9h5 M14 13h5 M6 17h13',arrow:'M5 12h14 M13 6l6 6-6 6',check:'M4 12l5 5L20 6'};
const ico=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.book}"/></svg>`;
const moduleDefs={eleves:['Élèves','Inscriptions et suivi des frais','people','blue'],enseignants:['Enseignants','Équipe et affectations','people','mint'],horaires:['Horaires','Classes, cours et enseignants','calendar','mint'],notes:['Résultats','Notes et suivi pédagogique','result','blue'],paiements:['Paiements','Validation et reçus','receipt','rose'],confirmations:['Parents','Confirmations des paiements','bell','gold'],budget:['Mes frais','Montants attendus et solde','money','blue'],recus:['Mes reçus','Historique des paiements','receipt','rose'],carte:['Ma carte','Mon identifiant scolaire','card','blue'],profil:['Mon profil','Mes informations scolaires','profile','mint']};
const moduleCard=(key)=>{const [label,sub,icon,color]=moduleDefs[key];return `<button class="module-card ${color}" data-tab="${key}"><span class="module-icon">${ico(icon)}</span><strong>${label}</strong><span>${sub}</span></button>`};
const basePortalContent=portalContent;
function dashboard(){let isStudent=role==='Élève',isTeacher=role==='Enseignant';let total=demo.students.reduce((n,s)=>n+s.due-s.paid,0);return `<div class="dash-welcome"><div><span class="eyebrow">VOTRE ESPACE SCOLAIRE</span><h1>${isStudent?'Bonjour, '+esc(student.name):isTeacher?'Bienvenue dans votre espace enseignant':'Bienvenue dans votre espace de gestion'}</h1><p>${isStudent?esc(student.section+' · '+student.classe):'Collège L’Harmattan · Travail, Maîtrise, Droiture'}</p></div><span class="session-pill">${esc(role)}</span></div><h2 class="dash-heading">${ico('bell')} Informations & annonces</h2><article class="announcement"><span class="announcement-tag">${isStudent?'Ma scolarité':'Vie du collège'}</span><h2>${isStudent?'Votre scolarité, en un seul endroit.':'Une vue claire sur la vie scolaire.'}</h2><p>${isStudent?'Consultez votre horaire, vos résultats et le suivi des frais depuis les cartes ci-dessous.':'Accédez aux élèves, aux cours et au suivi pédagogique depuis votre tableau de bord.'}</p><button class="btn" data-tab="horaires">${ico('calendar')} Consulter les horaires</button><span class="announcement-art">${ico('book')}</span></article><p class="demo-banner">Démonstration · Données fictives enregistrées dans ce navigateur. Aucun paiement réel ni message externe.</p>${!isTeacher?`<div class="dash-stats">${isStudent?`<article><span>Frais attendus</span><b>${student.due} <small>USD</small></b></article><article><span>Montant payé</span><b>${student.paid} <small>USD</small></b></article><article><span>Solde à payer</span><b>${student.due-student.paid} <small>USD</small></b></article>`:`<article><span>Élèves inscrits</span><b>${demo.students.length}</b></article><article><span>Enseignants</span><b>${demo.teachers.length}</b></article><article><span>Solde des frais</span><b>${total} <small>USD</small></b></article>`}</div>`:''}<h2 class="dash-heading">${ico('book')} ${isStudent?'Ma scolarité':'Pédagogie & organisation'}</h2><div class="module-grid trio">${(isStudent?['horaires','notes','carte']:isTeacher?['horaires','notes']:['eleves','enseignants','horaires','notes']).map(moduleCard).join('')}</div>${!isTeacher?`<h2 class="dash-heading">${ico('money')} ${isStudent?'Frais & paiements':'Finances & familles'}</h2><div class="module-grid">${(isStudent?['budget','recus']:['paiements','confirmations']).map(moduleCard).join('')}</div>`:''}<h2 class="dash-heading">${ico('profile')} Mon espace</h2><div class="module-grid">${moduleCard('profil')}</div>`}
portalContent=function(){if(tab==='dashboard')return dashboard();if(tab==='profil'||tab==='carte')return `<h2>${tab==='carte'?'Ma carte scolaire':'Mon profil'}</h2><article class="school-profile"><img src="./assets/logo.png" alt="Blason du collège"><div><span class="eyebrow">COLLÈGE L’HARMATTAN</span><h3>${esc(student&&role==='Élève'?student.name:role)}</h3><p>${role==='Élève'?esc(student.section+' · '+student.classe)+'<br>Identifiant : '+esc(student.id)+'<br>Parent lié : '+esc(student.parent||'Non renseigné'):'Espace de démonstration '+esc(role.toLowerCase())}</p><span class="session-pill">${tab==='carte'?'Carte de démonstration':esc(role)}</span></div></article>`;if(role!=='Élève')return basePortalContent();if(tab==='horaires')return `<h2>Mon horaire</h2><p>${esc(student.classe)} · Cours et enseignants affectés</p>${schedule(student.classe)}`;if(tab==='notes')return `<h2>Mes résultats</h2><p>Résultats de démonstration disponibles pour mon dossier.</p>${table(['Cours','Période','Résultat'],demo.results.filter(r=>r.student===student.id).map(r=>[esc(r.course),esc(r.period),r.score+' / '+r.max]))}`;if(tab==='budget')return `<h2>Mes frais scolaires</h2><div class="dash-stats"><article><span>Frais attendus</span><b>${student.due} USD</b></article><article><span>Total payé</span><b>${student.paid} USD</b></article><article><span>Solde</span><b>${student.due-student.paid} USD</b></article></div><p class="notice">Les montants affichés sont fictifs. Aucun paiement en ligne n’est effectué depuis cette démonstration.</p><button class="btn" data-tab="recus">Voir mes reçus</button>`;if(tab==='recus')return `<h2>Mes paiements et reçus</h2>${table(['Reçu','Montant','Mode','Référence'],demo.payments.filter(p=>p.student.split(' · ')[0]===student.id).map(p=>[esc(p.id),p.amount+' USD',esc(p.method),esc(p.reference)]))}<p>Seuls les paiements validés dans cette démonstration apparaissent ici. Un solde initial peut exister sans reçu détaillé.</p>`;return dashboard();};
const entryPage=pages.espace;
pages.espace=()=>{if(!role)return entryPage();const isStudent=role==='Élève';return `<div class="school-app"><div class="app-topbar"><a href="#accueil" class="app-brand"><img src="./assets/logo.png" alt="Blason"><div><b>L’HARMATTAN</b><span>${esc(role)}${isStudent?' · '+esc(student.classe):' · Plateforme scolaire'}</span></div></a><div class="app-top-actions"><button data-tab="${isStudent?'recus':'profil'}" class="icon-button" aria-label="${isStudent?'Mes reçus':'Mon profil'}">${ico('bell')}</button><button id="logout" class="exit-button">Quitter</button></div></div><section class="app-body">${tab!=='dashboard'?`<button class="back-button" data-tab="dashboard">← Tableau de bord</button><div class="module-title"><span class="eyebrow">${esc(role)} · L’HARMATTAN</span><p class="demo-inline">Données fictives · Démonstration</p></div>`:''}<div id="workspace" class="${tab==='dashboard'?'dashboard':'module-workspace'}">${portalContent()}</div></section><div class="bottom-nav" aria-label="Navigation de l’espace scolaire">${[['dashboard','Accueil','home'],[isStudent?'budget':role==='Enseignant'?'horaires':'paiements',isStudent?'Mes frais':role==='Enseignant'?'Horaires':'Paiements',isStudent?'money':role==='Enseignant'?'calendar':'receipt'],['notes','Résultats','result'],['profil','Profil','profile']].map(([key,label,icon])=>`<button data-tab="${key}" class="${tab===key?'selected':''}" ${tab===key?'aria-current="page"':''}>${ico(icon)}<span>${label}</span></button>`).join('')}</div></div>`};
const oldBindPortal=bindPortal;
bindPortal=function(){oldBindPortal();document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{role=b.dataset.role;tab='dashboard';render();window.scrollTo(0,0)});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();window.scrollTo(0,0)});const f=document.getElementById('student-login');if(f)f.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f));student=demo.students.find(s=>s.id===d.code.trim()&&s.name.toLowerCase()===d.name.trim().toLowerCase());if(student){role='Élève';tab='dashboard';render();window.scrollTo(0,0)}else document.getElementById('login-error').textContent='Nom ou code ID incorrect.'};document.body.classList.toggle('in-school-app',location.hash==='#espace'&&!!role);};

Object.assign(moduleDefs,{presences:['Présences','Suivi de présence','check','gold'],cours:['Cours','Tous les cours','book','blue'],documents:['Documents','Bulletins et pièces scolaires','book','gold'],annonces:['Publications & événements','Informations du collège','bell','rose']});
moduleDefs.horaires=['Horaire','Horaire de la classe','calendar','mint'];moduleDefs.notes=['Résultats','Notes et bulletins','result','mint'];moduleDefs.budget=['Mon budget','Frais scolaires et solde','money','blue'];moduleDefs.recus=['Paiement','Reçus et factures','receipt','rose'];
dashboard=function(){let pupil=role==='Élève';return `<h1 class="sun-heading">${ico('bell')} Informations & annonces</h1><article class="announcement"><span class="announcement-tag">COLLÈGE L’HARMATTAN</span><h2>Bienvenue dans votre espace scolaire</h2><p>${pupil?'Retrouvez votre horaire, vos cours, vos résultats et vos reçus. Votre dossier scolaire reste accessible depuis les rubriques ci-dessous.':'Retrouvez les élèves, les enseignants, les horaires et le suivi des paiements dans les rubriques ci-dessous.'}</p><button class="btn" data-tab="annonces">${ico('bell')} Voir les informations</button><span class="announcement-art">${ico('book')}</span></article><div class="carousel-position" aria-hidden="true"><i></i><i></i></div><div class="sun-alert"><span class="alert-symbol">${ico('card')}</span><div><strong>${pupil?'Mon dossier scolaire':'Espace de démonstration'}</strong><p>${pupil?esc(student.name)+' · '+esc(student.classe)+' · Identifiant : '+esc(student.id):'Sélectionnez une rubrique pour gérer les données fictives du collège.'} <b>Démonstration : aucune donnée réelle ni aucun message externe.</b></p><button data-tab="profil">${ico('profile')} Consulter mon profil</button></div></div><div class="module-grid sun-shortcuts">${['horaires','presences',pupil?'profil':'eleves'].map(moduleCard).join('')}</div><h2 class="dash-heading">${ico('book')} Formation</h2><div class="module-grid sun-shortcuts">${(pupil?['cours','notes','documents']:role==='Enseignant'?['cours','notes','enseignants']:['cours','enseignants','notes']).map(moduleCard).join('')}</div><h2 class="dash-heading">${ico('result')} Vue globale</h2><div class="module-grid sun-overview">${(pupil?['budget','recus','carte','documents','annonces','profil']:role==='Enseignant'?['eleves','horaires','annonces','profil']:['eleves','paiements','confirmations','horaires','annonces','profil']).map(moduleCard).join('')}</div><p class="app-credit">Conçu et développé par AMMGROUP Digital</p>`};
const sunContent=portalContent;
portalContent=function(){if(tab==='cours')return `<h2>${role==='Élève'?'Mes cours':'Cours et affectations'}</h2>${table(['Cours','Classe','Enseignant'],demo.slots.filter(s=>role!=='Élève'||s.classe===student.classe).map(s=>[esc(s.course),esc(s.classe),esc(s.teacher)]))}`;if(tab==='presences')return `<h2>Présences</h2><p>Aucun relevé de présence n’a encore été saisi dans cette démonstration.</p><p class="notice">Le suivi des présences sera renseigné par l’équipe du collège. Aucun relevé réel n’est disponible.</p>`;if(tab==='documents')return `<h2>Documents scolaires</h2><p>Aucun bulletin ni document scolaire n’a encore été déposé.</p><button class="btn" data-tab="notes">Consulter les résultats disponibles</button>`;if(tab==='annonces')return `<h2>Informations du collège</h2><article class="notice"><h3>Travail, Maîtrise, Droiture</h3><p>Collège L’Harmattan · Avenue Bunduki, Golf Karavia, Plateau Karavia · Lubumbashi.</p><p>Les annonces officielles seront ajoutées après leur transmission par le collège.</p></article>`;return sunContent();};
const schoolLayout=pages.espace;
pages.espace=()=>{if(!role){role='Élève';student=demo.students[0];tab='dashboard';}return schoolLayout().replace('<section class="app-body">',`<div class="demo-switch"><span>Aperçu :</span>${['Élève','Enseignant','Administration'].map(r=>`<button data-role="${r}" class="${role===r?'current':''}">${r}</button>`).join('')}</div><section class="app-body">`);};
const sunBind=bindPortal;
bindPortal=function(){sunBind();const logout=document.getElementById('logout');if(logout)logout.onclick=()=>{role='';student=null;location.hash='accueil';};document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{role=b.dataset.role;if(role==='Élève')student=demo.students[0];tab='dashboard';render();window.scrollTo(0,0);});};

function render(){const page=location.hash.slice(1)||'accueil';main.innerHTML=(pages[page]||pages.accueil)();document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+page));document.querySelector('nav').classList.remove('open');document.querySelector('#menu').setAttribute('aria-expanded','false');document.title=`${({accueil:'Accueil',college:'Le collège',sections:'Nos sections',admissions:'Admissions',contact:'Contact',espace:'Espace scolaire'})[page]||'Accueil'} · Collège L’Harmattan`;bindAdmission();bindPortal();}window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});document.querySelector('#menu').onclick=()=>{const open=document.querySelector('nav').classList.toggle('open');document.querySelector('#menu').setAttribute('aria-expanded',String(open));};render();
